"use client";

import { services } from "@/data/services";
import { Check, Clock, Tag, ArrowRight } from "lucide-react";
import Link from "next/link";
import FinalCTA from "@/components/sections/FinalCTA";

export default function ServicesPage() {
  return (
    <div className="pt-44 pb-24">
      {/* Header */}
      <section className="px-6 mb-24">
        <div className="max-w-7xl mx-auto text-center">
          <p className="text-primary text-sm font-bold uppercase tracking-[0.3em] mb-4">
            Our Offerings
          </p>
          <h1 className="text-5xl md:text-7xl font-black text-white mb-8 font-outfit">
            Digital Engineering <br />
            <span className="text-gradient">Redefined.</span>
          </h1>
          <p className="text-foreground/60 text-lg md:text-xl max-w-2xl mx-auto leading-relaxed">
            We deliver high-performance solutions tailored for growth and scale. 
            Every service is backed by our expert collective of senior engineers.
          </p>
        </div>
      </section>

      {/* Services List */}
      <section className="px-6 space-y-32">
        {services.map((service, index) => (
          <div 
            key={service.id} 
            id={service.id}
            className="max-w-7xl mx-auto"
          >
            <div className={`grid grid-cols-1 lg:grid-cols-2 gap-16 items-start ${index % 2 !== 0 ? 'lg:flex-row-reverse' : ''}`}>
              <div className={index % 2 !== 0 ? 'lg:order-2' : ''}>
                <div className="inline-flex items-center gap-2 px-4 py-2 bg-primary/10 border border-primary/20 rounded-full text-primary text-xs font-bold uppercase tracking-widest mb-6">
                  Featured Service
                </div>
                <h2 className="text-4xl md:text-5xl font-bold text-white mb-6 font-outfit">
                  {service.title}
                </h2>
                <p className="text-foreground/70 text-lg leading-relaxed mb-10">
                  {service.description}
                </p>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-8 gap-y-4 mb-12">
                  {service.features.map(feature => (
                    <div key={feature} className="flex items-start gap-3">
                      <div className="w-5 h-5 bg-primary/20 rounded-full flex items-center justify-center shrink-0 mt-1">
                        <Check className="w-3 h-3 text-primary" />
                      </div>
                      <span className="text-white/80 text-sm font-medium">{feature}</span>
                    </div>
                  ))}
                </div>

                <div className="flex flex-wrap gap-8 items-center border-t border-border/40 pt-8">
                  <div className="flex items-center gap-2">
                    <Tag className="w-5 h-5 text-primary" />
                    <div>
                      <p className="text-[10px] uppercase text-white/40 tracking-wider">Investment</p>
                      <p className="text-white font-bold">{service.pricingHint}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <Clock className="w-5 h-5 text-primary" />
                    <div>
                      <p className="text-[10px] uppercase text-white/40 tracking-wider">Timeline</p>
                      <p className="text-white font-bold">{service.timeline}</p>
                    </div>
                  </div>
                  <Link 
                    href="/contact"
                    className="ml-auto px-8 py-4 bg-white text-black rounded-xl font-bold hover:scale-105 transition-transform flex items-center gap-2"
                  >
                    Get Started <ArrowRight className="w-4 h-4" />
                  </Link>
                </div>
              </div>

              <div className={`relative ${index % 2 !== 0 ? 'lg:order-1' : ''}`}>
                <div className="aspect-square rounded-[3rem] overflow-hidden glass border-primary/20 relative group">
                  <div className="absolute inset-0 bg-gradient-to-br from-primary/20 via-transparent to-accent/20" />
                  <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-32 h-32 bg-primary/30 blur-[80px] rounded-full group-hover:w-64 group-hover:h-64 transition-all duration-700" />
                  
                  {/* Decorative Elements */}
                  <div className="absolute inset-12 border border-white/10 rounded-[2rem] flex items-center justify-center">
                    <div className="text-center p-12">
                      <h4 className="text-white/20 text-4xl font-black uppercase tracking-[0.2em] transform -rotate-12 select-none">
                        {service.title}
                      </h4>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        ))}
      </section>

      <FinalCTA />
    </div>
  );
}
